#!/usr/bin/env bash
# The graph is generated by the real Visual Builder, then run by the actual
# plugin; no mocked graphics or precomputed fixture source is substituted.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
module="$(realpath "${1:-$root/build_x86_64/hypershader.so}")"
work="$(mktemp -d /tmp/hs-persistent-builder-XXXXXX)"
trap 'rm -rf "$work"' EXIT
cp -a --reflink=auto "${2:-$root/data}" "$work/data"
effect="$work/data/shaders/generated-persistent.effect"
HS_PERSISTENT_EFFECT="$effect" node "$root/scripts/verify-persistent-builder.js"
"$root/scripts/verify-two-buffer-graph.sh" "$module" "$work/data" "$effect" source-builder
